import {TownScene} from './scene.js';
import {UTILS,LABELS,VERSION,parseOSM,createTown,flows,demand,monthlyReads,exportTown,round,terrain} from './model.js';
import {inspectSnapshot,StateReceiver,traceConnection,displayQuantity} from './adapter.js';
const $=id=>document.getElementById(id);
const fmt=(x,d=0)=>x===null||x===undefined?'—':Number(x).toLocaleString('en-CA',{maximumFractionDigits:d,minimumFractionDigits:d});
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let town,source,scene,inspection,receiver,flow,selected=null,asset=null,assetNode=null,utility='electric';
let mode='demo',hour=8,scenario='normal',target=null,playing=false,timer=null,fixture='actual',busy=false,frames=[],frameIndex=0,toastTimer;
const tick=()=>Math.round(hour*12);
function toast(message){$('toast').textContent=message;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),5000);}
function download(obj,name,type='application/json'){const url=URL.createObjectURL(new Blob([typeof obj==='string'?obj:JSON.stringify(obj,null,2)],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function quantity(v,unit,u,absolute=false){const d=displayQuantity(v,unit,u);return `${fmt(d.value===null?null:absolute?Math.abs(d.value):d.value,u==='electric'?2:3)} ${d.unit}`;}
function getState(){return {townId:town?.id,mode,seed:town?.seed,homes:town?.count,scenario:mode==='demo'?scenario:null,simTime:receiver?.frame?.simTime||null,sequence:receiver?.lastSequence??null,selectedPremiseId:selected?.id||null,layers:scene?.layers,validation:town?.validation};}
function stop(){playing=false;clearInterval(timer);timer=null;$('play-btn').textContent='▶';$('play-btn').setAttribute('aria-label','Play');$('tick-status').textContent='Paused';}
function emptyFlow(t){const f={homes:new Map(t.premises.map(h=>[h.id,{electric:null,water:null,gas:null}]))};for(const u of UTILS)f[u]={source:null,unit:t.networks[u].unit,edgeFlows:new Map(),edgeEnabled:new Map()};return f;}
function refreshMode(){
 const imported=mode==='snapshot';$('source-badge').textContent=imported?'ENGINE SNAPSHOT':'DEMO FIXTURE';$('source-badge').classList.toggle('engine',imported);
 $('source-note').textContent=imported?'Geometry and measurements come from the loaded engine files.':'Browser fixtures for design. Load an engine snapshot to inspect its data.';
 $('load-state-btn').hidden=!imported;$('return-demo').hidden=!imported;$('scenario').disabled=imported;
 $('generator-section').hidden=imported;$('play-btn').disabled=imported&&frames.length<2;$('hour').disabled=imported&&frames.length<2;
 $('time-mode-label').textContent=imported?'Engine replay':'5-minute steps';
 $('timeline-ticks').hidden=imported;if(!imported)$('state-status').textContent='';$('hour').max=String(imported?Math.max(0,frames.length-1):287);
 if(imported)$('scenario-note').textContent='Scenario outcomes are read from the engine. This viewer does not run a second simulation.';
}
function mount(next,nextMode){
 const nextInspection=inspectSnapshot(next,{legacyTerrain:terrain});
 // Validate embedded state before replacing the visible town.
 const nextReceiver=new StateReceiver(nextInspection);if(next.stateFrame)nextReceiver.accept(next.stateFrame);
 stop();scene.load(next);town=next;mode=nextMode;inspection=nextInspection;receiver=nextReceiver;frames=[];frameIndex=0;selected=null;asset=null;assetNode=null;$('inspector').hidden=true;
 $('homes-count').textContent=fmt(town.count);$('services-count').textContent=fmt((town.servicePoints||[]).length);$('solar-count').textContent=fmt(town.premises.filter(h=>h.solar).length);
 $('map-title').textContent=nextMode==='demo'?`Whitby / ${String(town.seed).split('-').at(-1)}`:(town.name||'Engine town');$('town-title').textContent=nextMode==='demo'?'Whitby-inspired':town.schemaVersion;
 $('integrity-status').textContent=nextMode==='demo'?'Every service connected':'Snapshot structure checked';$('integrity-detail').textContent=nextMode==='demo'?`${fmt(town.validation.networkEdges)} edges · 0 orphaned services`:'Endpoints, terrain and identifiers valid';
 $('runtime-info').textContent=nextMode==='demo'?`Demo generator v${VERSION}`:`${town.id} · topology ${inspection.topologyRevision}`;
 $('search-results').hidden=true;target=town.premises.find(h=>h.occupied)?.id;refreshMode();
 if(mode==='demo'){hour=8;scenario='normal';$('scenario').value='normal';updateFlow();updateScenarioNote();}else{flow=receiver.flow||emptyFlow(town);renderFlow();if(receiver.frame)showClock(receiver.frame);else{$('time-label').textContent='—';$('date-label').textContent='AWAITING ENGINE STATE';scene.setClock({sunElevationDeg:45,sunAzimuthDeg:135});$('clock-icon').textContent='◷';$('clock-status').textContent='No state';}}
 return getState();
}
async function generate(seed=$('seed').value,count=Number($('size').value)){
 if(busy)throw Error('Town generation is already running.');busy=true;$('generate-btn').disabled=true;$('loading').hidden=false;await new Promise(r=>setTimeout(r,25));
 try{const start=performance.now(),next=createTown(source,{seed,count});if(!next.validation.valid)throw Error(next.validation.errors.join(', '));mount(next,'demo');$('seed').value=town.seed;$('size').value=String(town.count);$('runtime-info').textContent=`Demo v${VERSION} · ${Math.round(performance.now()-start)} ms generation & scene`;return getState();}
 finally{busy=false;$('generate-btn').disabled=false;$('loading').hidden=true;}
}
function demoClock(){const elevation=55*Math.sin((hour-6)/12*Math.PI);scene.setClock({sunElevationDeg:elevation,sunAzimuthDeg:90+(hour-6)*15});$('clock-icon').textContent=elevation>0?'☀':'☾';$('clock-status').textContent=elevation>0?'Day · demo lighting':'Night · demo lighting';const hrs=Math.floor(hour),mins=Math.round((hour-hrs)*60);$('time-label').textContent=`${String(hrs).padStart(2,'0')}:${String(mins).padStart(2,'0')}`;$('date-label').textContent='15 JUL 2026 · EDT';$('hour').value=String(tick());}
function renderFlow(){scene.setFlows(flow);for(const u of UTILS){const v=flow[u].source;$('flow-'+u).textContent=v===null?'No state received':`${quantity(v,flow[u].unit,u,true)} ${u==='electric'?(v<0?'export':'import'):'supplied'}`;}if(selected){const active=document.activeElement;if(!active||!$('inspector').contains(active)||!['SELECT','INPUT'].includes(active.tagName))renderHome();}else if(asset)renderAsset();}
function updateFlow(){if(!town||mode!=='demo')return;flow=flows(town,hour,scenario==='solar'?'normal':scenario,target);renderFlow();demoClock();}
function showClock(frame){const c=frame.clock||{simTime:frame.simTime,timezone:'America/Toronto'},d=new Date(c.simTime);$('time-label').textContent=new Intl.DateTimeFormat('en-GB',{timeZone:c.timezone,hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(d);$('date-label').textContent=new Intl.DateTimeFormat('en-CA',{timeZone:c.timezone,day:'2-digit',month:'short',year:'numeric',timeZoneName:'short'}).format(d);if(Number.isFinite(c.sunElevationDeg)){scene.setClock(c);$('clock-icon').textContent=c.sunElevationDeg>0?'☀':'☾';$('clock-status').textContent=c.sunElevationDeg>0?'Day · engine clock':'Night · engine clock';}else{scene.setClock({sunElevationDeg:45,sunAzimuthDeg:135});$('clock-icon').textContent='◷';$('clock-status').textContent='Engine time · neutral light';}$('state-status').textContent=`Frame ${frame.sequence} · ${frame.simulationId}`;}
function applyFrame(index,seek=false){if(seek)receiver.reset();const frame=frames[index],result=receiver.accept(frame);frameIndex=index;flow=result.flow;showClock(frame);renderFlow();$('hour').value=String(index);if(selected)scene.select(selected,utility);}
function setHour(value){if(mode!=='demo')throw Error('The engine owns simulation time. Load a replay to seek.');if(!Number.isFinite(value)||value<0||value>=24)throw Error('Hour must be from 0 to 23.9167.');hour=Math.round(value*12)/12;updateFlow();}
function setLayer(u,on){scene.layers[u]=on;scene.setLayers(scene.layers);for(const type of UTILS){$('layer-'+type).classList.toggle('active',scene.layers[type]);$('layer-'+type).setAttribute('aria-pressed',String(scene.layers[type]));}$('map-mode').textContent=UTILS.filter(u=>scene.layers[u]).map(u=>LABELS[u]).join(' + ')||'Town landscape';}
function updateScenarioNote(){const h=town?.premises.find(h=>h.id===target);$('scenario-note').textContent={normal:'Demand changes with the hour. Solar homes can send power back upstream.',solar:'At noon, rooftop generation can exceed demand. Watch the flow reverse.',leak:`A 650 L/h leak at ${h?.id||'one home'}. Extra demand travels through its upstream pipes.`,outage:'The substation is off. Grid-tied solar shuts down; islanding is not modelled.'}[scenario];}
function setScenario(value){if(mode!=='demo')throw Error('Scenario commands belong to the engine; this loaded snapshot is read-only.');if(!['normal','solar','leak','outage'].includes(value))throw Error('Unknown scenario.');scenario=value;$('scenario').value=value;if(value==='solar'){setLayer('electric',true);hour=12;const h=town.premises.find(h=>h.solar&&h.occupied);if(h)selectHome(h,false);}if(value==='leak'){setLayer('water',true);utility='water';if(selected)target=selected.id;const h=town.premises.find(h=>h.id===target);if(h)selectHome(h,true);}updateFlow();updateScenarioNote();}
function selectHome(h,focus=false){selected=h;asset=null;fixture='actual';if(!h.services[utility])utility=Object.keys(h.services)[0];$('inspector').hidden=false;scene.select(h,utility,focus);renderHome();}
function line(label,value,mono=false){return `<div class="detail-line"><span>${escape(label)}</span><strong class="${mono?'mono':''}">${value}</strong></div>`;}
function sampleForHome(){
 if(mode==='snapshot')return (town.sampleReads||[]).filter(r=>r.premiseId===selected.id&&r.commodity===utility).sort((a,b)=>String(b.periodEnd||'').localeCompare(String(a.periodEnd||'')));
 let reads=monthlyReads(town,selected).filter(r=>r.commodity===utility).map(r=>({...r}));if(fixture!=='actual')reads=reads.map(r=>{if(r.direction==='export')return r;const read={...r,id:r.id+'-'+fixture,idempotencyKey:r.idempotencyKey+':'+fixture};if(fixture==='stuck'){read.registerValue=read.previousRegisterValue;read.consumption=0;read.reasonCode='SIM_STUCK_REGISTER';}if(fixture==='missing'){read.registerValue=null;read.consumption=null;read.scheduledReadAt=read.readAt;read.readAt=null;read.readType='missing';read.readStatus='missing';read.reasonCode='SIM_TELEMETRY_FAILURE';}if(fixture==='spike'){read.consumption=round(r.consumption*8);read.registerValue=round(r.previousRegisterValue+read.consumption);read.reasonCode='SIM_SPIKE';}return read;});return reads;
}
function renderHome(){
 const h=selected,reads=sampleForHome(),r=reads.find(r=>r.direction!=='export')||reads[0],value=flow.homes.get(h.id)?.[utility]??null;
 const route=traceConnection(town,h.id,utility,flow[utility].edgeEnabled),dist=route.edges.reduce((a,e)=>a+e.lengthM,0),net=town.networks[utility];
 const nodeById=new Map(net.nodes.map(n=>[n.id,n]));const routeNodes=[];if(route.connected){let cursor=route.sourceId;routeNodes.push(nodeById.get(cursor));for(const e of route.edges){cursor=e.from===cursor?e.to:e.from;routeNodes.push(nodeById.get(cursor));}}
 const milestones=routeNodes.filter(n=>['external_supply','substation','pump_station','city_gate_regulator','transformer','meter'].includes(n.kind));
 const chain=route.connected?milestones.slice(0,8).map(n=>`<div>${escape(n.label||n.kind.replaceAll('_',' '))}<small>${escape(n.id)}</small></div>`).join(''):`<div>${escape(route.reason)}</div>`;
 const live=quantity(value,net.unit,utility,true),caption=value===null?'Awaiting engine measurements':utility==='electric'?(value<0?'Exporting to the grid':value===0?'No power flow':'Drawing from the grid'):'Flow into this property';
 let chart='';if(mode==='demo'){const points=Array.from({length:24},(_,i)=>demand(h,i+.5,scenario==='solar'?'normal':scenario,target)[utility]),max=Math.max(.01,...points.map(Math.abs));chart=`<div class="spark-chart">${points.map(v=>`<span title="${quantity(v,net.unit,utility)}" style="height:${Math.max(2,Math.abs(v)/max*100)}%;background:${v<0?'#cda142':utility==='water'?'#70abb0':utility==='gas'?'#ad97bf':'#8da57b'}"></span>`).join('')}</div><div class="spark-label"><span>00:00</span><span>Demo demand profile</span><span>24:00</span></div>`;}
 const readSection=r?`${mode==='demo'?'<select id="fixture" aria-label="Meter reading fixture"><option value="actual">Actual reading</option><option value="stuck">Stuck register</option><option value="missing">Missing telemetry</option><option value="spike">8× consumption spike</option></select>':''}${line('Previous register',quantity(r.previousRegisterValue,r.unit,utility))}${line('Reported register',quantity(r.registerValue,r.unit,utility))}${line('Consumption',quantity(r.consumption,r.unit,utility))}${line('Read status',escape(r.readStatus||'Not supplied'))}<p class="small-note">${escape(r.periodStart?.slice(0,10)||'')} to ${escape(r.periodEnd?.slice(0,10)||'')} · ${mode==='demo'?'June baseline; independent of the live July scenario.':'Values supplied by the engine.'}</p><button id="download-read" class="outline-btn">Export read for VEE</button><p class="small-note">Ground truth is excluded from this export.</p>`:'<p class="small-note">No read records supplied for this service.</p>';
 $('inspector-body').innerHTML=`<div class="eyebrow">PREMISE / ${escape(h.id)}</div><h2>${escape(h.address)}</h2><div class="address">${mode==='demo'?'Synthetic home':'Engine premise'} · ${fmt(h.width*h.depth)} m² footprint</div><div class="home-tags"><span>${h.occupied?fmt(h.occupants)+' residents':'Vacant'}</span>${h.solar?'<span>☀ '+fmt(h.solarKW,1)+' kW solar</span>':''}${h.electricHeat?'<span>Electric heating</span>':''}</div><button id="focus-home" class="outline-btn">Locate this home</button><div class="inspector-tabs">${UTILS.filter(u=>h.services[u]).map(u=>`<button data-utility="${u}" class="${u===utility?'active':''}">${LABELS[u]}</button>`).join('')}</div><div class="big-number ${utility}">${escape(live)}</div><div class="flow-caption">${caption}</div>${chart}<div class="detail-section"><h3>${route.connected?'Source connection':'Service isolated'}</h3><div class="chain">${chain}</div>${line('Connection route',route.connected?fmt(dist)+' m':'No active route')}${line('Service point',escape(h.services[utility]),true)}<p class="small-note">Connectivity route through enabled links. In a looped network, this is not the complete flow solution.</p></div><div class="detail-section"><h3>${mode==='demo'?'Monthly read fixture':'Latest supplied read'}</h3>${readSection}</div><div class="detail-section"><h3>Meter to invoice</h3>${line('Read',escape(r?.readStatus||'Not supplied'))}${line('VEE',escape(r?.veeStatus||'Not supplied'))}${line('Billing document',escape(r?.billingDocumentId||'Not supplied'))}${line('Invoice',escape(r?.invoiceId||'Not supplied'))}${line('Contract account',escape(h.accountId),true)}</div>`;
 if($('fixture')){$('fixture').value=fixture;$('fixture').onchange=e=>{fixture=e.target.value;renderHome();};}
 $('focus-home').onclick=()=>scene.select(h,utility,true);
 if($('download-read'))$('download-read').onclick=()=>{const safe=sampleForHome().map(({truth,...r})=>r);download({schemaVersion:'vee-input-fixture/1.1',reads:safe},`${h.id}-${utility}-vee-input.json`);};
 document.querySelectorAll('[data-utility]').forEach(btn=>btn.onclick=()=>{utility=btn.dataset.utility;fixture='actual';setLayer(utility,true);scene.select(h,utility);renderHome();});
}
function renderAsset(){const u=asset,net=town.networks[u],n=net.nodes.find(n=>n.id===(assetNode||net.stationId)),v=flow[u].source;if(!n)return;$('inspector-body').innerHTML=`<div class="eyebrow">SUPPLY INFRASTRUCTURE</div><h2>${escape(n.label||n.kind)}</h2><div class="address">${escape(n.id)} · ${LABELS[u]}</div><div class="big-number ${u}">${escape(quantity(v,net.unit,u,true))}</div><div class="flow-caption">${v===null?'Awaiting engine measurements':'Total network boundary flow'}</div><div class="detail-section">${line('Network edges',fmt(net.edges.length))}${line('Network layout',escape(net.topology||'Engine supplied'))}${line('Elevation',fmt(n.elevationM,2)+' m')}</div><p class="small-note">${mode==='demo'?'Illustrative flow balance. Pressure, voltage drop and capacity are not solved.':'Geometry and measurements are rendered from the supplied engine data. Unknown measurements remain blank.'}</p>`;}
function closeInspector(){selected=null;asset=null;$('inspector').hidden=true;scene.clearSelection();}
function searchHomes(query){const q=query.trim().toLowerCase();if(!q)return[];return town.premises.filter(h=>h.id.toLowerCase()===q||h.id===`P-${q.padStart(5,'0')}`||String(h.address).toLowerCase().includes(q)).slice(0,8);}
function showSearch(){const hits=searchHomes($('search-input').value);$('search-results').hidden=false;$('search-results').innerHTML=hits.length?hits.map(h=>`<button data-home="${escape(h.id)}">${escape(h.address)}<small>${escape(h.id)}${h.solar?' · Solar home':''}</small></button>`).join(''):'<div class="empty-state">No matching homes. Try a number such as 42.</div>';document.querySelectorAll('[data-home]').forEach(b=>b.onclick=()=>{selectHome(town.premises.find(h=>h.id===b.dataset.home),true);$('search-results').hidden=true;});}
function blueprint(){
 $('blueprint-body').innerHTML=`<p class="blueprint-intro">The engine owns the town and every simulated outcome. This viewer renders its snapshots and state frames, with a separate browser fixture mode for design.</p><div class="blueprint-grid"><div class="blueprint-card"><h3>Viewer owns</h3><p>3D terrain, buildings, network layers, signed flow particles, connection inspection, readable units and engine-driven day/night lighting.</p></div><div class="blueprint-card"><h3>Engine owns</h3><p>Generation, topology, physics, time, demand, incidents, crews, meter readings, VEE, billing and invoices. Loaded snapshots are never re-simulated in the browser.</p></div></div><h3 class="blueprint-subtitle">Load the handoff</h3><p class="blueprint-intro">Use Load engine snapshot for a utility-town/2.0 JSON file. Then load state frames as a single utility-state/1.0 frame or a utility-replay/1.0 bundle. Town, topology and index revisions must match. Replay controls move through supplied frames.</p><p class="small-note">No state means no animated flow. Unknown values stay blank. Gas is displayed in CCF; stored data remain SI. Looped network traces show connectivity, not a hydraulic solution. Engine changes to network structure require a new snapshot.</p><h3 class="blueprint-subtitle">Current delivery</h3><p class="small-note">Snapshot, heightmap, frame and loop-trace adapters are implemented. The live engine API, Arrow decoding, crew animations, work queue screens and billing overlays await the engine's corresponding outputs. The browser fixture remains illustrative. Automated model and contract tests do not establish browser FPS.</p><div class="blueprint-actions"><a href="./VIEWER_ENGINE_HANDOFF.md" download>Shared viewer handoff</a><a href="./REQUIREMENTS.md" download>Original town requirements</a></div>`;$('blueprint').showModal();
}
async function readJSON(file){if(!file)throw Error('Choose a JSON file.');if(file.size>100*1024*1024)throw Error('File exceeds the 100 MB viewer limit.');return JSON.parse(await file.text());}
function wire(){
 for(const u of UTILS)$('layer-'+u).onclick=()=>setLayer(u,!scene.layers[u]);$('show-services').onchange=e=>scene.setXray(e.target.checked);
 $('hour').oninput=e=>{try{mode==='demo'?setHour(Number(e.target.value)/12):applyFrame(Number(e.target.value),true);}catch(e){toast(e.message);}};
 $('scenario').onchange=e=>{try{setScenario(e.target.value);}catch(e){toast(e.message);}};$('generate-btn').onclick=()=>generate().then(()=>toast('Demo town regenerated.')).catch(e=>toast(e.message));$('seed').onkeydown=e=>{if(e.key==='Enter')$('generate-btn').click();};$('reset-seed').onclick=()=>{$('seed').value='WHITBY-042';};
 $('home-view').onclick=()=>scene.home();$('top-view').onclick=()=>scene.top();$('zoom-in').onclick=()=>scene.zoom(.75);$('zoom-out').onclick=()=>scene.zoom(1.3);$('close-inspector').onclick=closeInspector;
 $('search-form').onsubmit=e=>{e.preventDefault();showSearch();};$('search-input').oninput=()=>{$('search-input').value?showSearch():$('search-results').hidden=true;};
 $('play-btn').onclick=()=>{if(playing){stop();return;}playing=true;$('play-btn').textContent='Ⅱ';$('play-btn').setAttribute('aria-label','Pause');$('tick-status').textContent=mode==='demo'?'1 day / 72 seconds':'Playing supplied frames';timer=setInterval(()=>{if(busy)return;try{if(mode==='demo')setHour(((tick()+1)%288)/12);else if(frameIndex+1<frames.length)applyFrame(frameIndex+1);else stop();}catch(e){stop();toast(e.message);}},250);};
 $('requirements-btn').onclick=blueprint;$('limits-btn').onclick=blueprint;$('close-blueprint').onclick=()=>$('blueprint').close();
 $('export-btn').onclick=async()=>{$('export-btn').disabled=true;await new Promise(r=>setTimeout(r,25));try{download(mode==='demo'?exportTown(town):town,`${town.id}-snapshot.json`);toast('Snapshot exported.');}catch(e){toast(e.message);}finally{$('export-btn').disabled=false;}};
 $('import-btn').onclick=()=>$('osm-file').click();$('osm-file').onchange=async e=>{const old=source;try{source=parseOSM(await readJSON(e.target.files[0]));await generate();toast('OSM roads imported into the demo generator.');}catch(e){source=old;toast(e.message);}finally{$('osm-file').value='';}};
 $('load-snapshot-btn').onclick=()=>$('snapshot-file').click();$('snapshot-file').onchange=async e=>{try{mount(await readJSON(e.target.files[0]),'snapshot');toast('Engine snapshot loaded.');}catch(e){toast('Snapshot rejected: '+e.message);}finally{$('snapshot-file').value='';}};
 $('return-demo').onclick=()=>generate().catch(e=>toast(e.message));
 $('load-state-btn').onclick=()=>$('state-file').click();$('state-file').onchange=async e=>{try{const json=await readJSON(e.target.files[0]);if(json.schemaVersion!=='utility-state/1.0'&&json.schemaVersion!=='utility-replay/1.0')throw Error('Unsupported state/replay version.');const incoming=json.schemaVersion==='utility-replay/1.0'?json.frames:[json];if(!Array.isArray(incoming)||!incoming.length||incoming.length>2000)throw Error('Replay must contain 1–2,000 complete frames.');const check=new StateReceiver(inspection);for(const f of incoming)check.accept(f);stop();frames=incoming;receiver.reset();refreshMode();applyFrame(0);toast(`${frames.length} engine frame${frames.length===1?'':'s'} loaded.`);}catch(e){toast('State rejected: '+e.message);}finally{$('state-file').value='';}};
 document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeInspector();$('search-results').hidden=true;}});
}
function registerTools(){const ctx=document.modelContext;if(!ctx?.registerTool)return;for(const t of [{name:'read_town_state',description:'Read viewer mode, town identity, active frame and selected premise.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:getState},{name:'select_town_premise',description:'Select and focus an existing premise.',inputSchema:{type:'object',properties:{premiseId:{type:'string'}},required:['premiseId'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{const h=town.premises.find(h=>h.id===input?.premiseId);if(!h)throw Error('Premise not found.');selectHome(h,true);return getState();}}])try{Promise.resolve(ctx.registerTool(t)).catch(()=>{});}catch{}}
try{const response=await fetch('./whitby-roads.json');if(!response.ok)throw Error('Street fixture could not be loaded.');source=parseOSM(await response.json());scene=new TownScene($('map'),({home,asset:u,nodeId})=>{if(home)selectHome(home);else if(u){asset=u;assetNode=nodeId;selected=null;scene.clearSelection();$('inspector').hidden=false;renderAsset();}});scene.play=!matchMedia('(prefers-reduced-motion: reduce)').matches;wire();await generate();registerTools();}
catch(e){console.error(e);$('loading').hidden=false;$('loading').innerHTML=`<div class="error-state"><strong>The town could not open.</strong><p>${escape(e.message)}</p><p>This 3D view needs WebGL enabled.</p><button onclick="location.reload()">Try again</button></div>`;}
